// Text init writes or prints. Pure: every function maps its input to a string.

export const DOCS = 'https://github.com/avas-app/agent-bridge/blob/main/docs'
export const FLOW_GLOB = '**/*.flow.*'

/** An app variable the generated file imports, with its path from that file. */
export type Imported = { name: string; from: string }

export type RealtimeTodo = {
  kind: 'socket.io' | 'ably'
  /** The client variable, when the scan found one. */
  name?: string
  /** The file that creates it, relative to the app, when found. */
  file?: string
}

export type BridgeFileInput = {
  version: string
  appName: string
  ts: boolean
  expo: boolean
  expoRouter: boolean
  reactQuery: boolean
  webview: boolean
  network: boolean
  /** @react-navigation/native without expo-router. */
  reactNavigation: boolean
  /** Undefined when zustand isn't a dependency; empty when the scan found no store. */
  stores?: Imported[]
  mmkv?: Imported[]
  realtime: RealtimeTodo[]
  /** Realtime tools the app already exports, wired live. */
  realtimeTools?: Imported[]
}

const REALTIME = {
  'socket.io': { fn: 'socketIoTools', from: '@avasapp/agent-bridge/socket.io', client: 'socket' },
  ably: { fn: 'ablyTools', from: '@avasapp/agent-bridge/ably', client: 'ably' },
} as const

export const STORES_WHY =
  'stores often hold tokens: add `redact` for those paths before wiring them'
export const MMKV_WHY =
  'MMKV often holds tokens and mmkv.get returns values as they are: wire only instances without secrets'
export const REALTIME_WHY =
  'the adapter must wrap the client where it is created, before the app subscribes'
export const NETWORK_PROMPT =
  'Wire network tools? In dev builds they patch fetch and XMLHttpRequest so the agent can log and mock requests.'
export const NETWORK_WHY =
  'networkTools patches fetch and XMLHttpRequest in dev builds so the agent can log and mock requests (net.*); it also enables the offline scenario'

/** `useAuthStore` → `auth`. */
export const storeKey = (name: string) => {
  const bare = name.replace(/^use/, '').replace(/Store$/, '') || name
  return bare[0]!.toLowerCase() + bare.slice(1)
}

/** One line to add where a realtime client is created. */
export function realtimeLine(todo: RealtimeTodo): string {
  const r = REALTIME[todo.kind]
  return `export const realtimeDevTools = ${r.fn}(${todo.name ?? r.client})`
}

export function realtimeTodoText(todo: RealtimeTodo): string {
  const r = REALTIME[todo.kind]
  const where = todo.file
    ? `In ${todo.file}, right after \`${todo.name}\` is created`
    : `Where your ${todo.kind} client is created`
  return `${where}, add \`${realtimeLine(todo)}\` (import { ${r.fn} } from '${r.from}'), then spread realtimeDevTools into tools`
}

/** The dev-only component that mounts the bridge. */
export function renderBridgeFile(o: BridgeFileInput): string {
  const L: string[] = []
  const core = ['cdpTransport', ...(o.ts ? ['type Scenarios'] : []), 'useAgentBridge']
  L.push(
    `// Generated by agent-bridge init ${o.version}. Yours to edit: init skips this file unless --force.`,
    `import { ${core.join(', ')} } from '@avasapp/agent-bridge'`,
  )
  if (o.expo) L.push(`import { expoTransport } from '@avasapp/agent-bridge/expo'`)
  if (o.expoRouter) L.push(`import { routerTools } from '@avasapp/agent-bridge/expo-router'`)
  if (o.network)
    L.push(`import { networkTools, strictNetwork } from '@avasapp/agent-bridge/network'`)
  if (o.webview)
    L.push(`import { webviewTools } from '@avasapp/agent-bridge/react-native-webview'`)
  if (o.reactQuery) {
    L.push(
      `import { queryTools } from '@avasapp/agent-bridge/tanstack-query'`,
      `import { QueryClientContext } from '@tanstack/react-query'`,
    )
  }
  if (o.expoRouter) L.push(`import { router, useNavigationContainerRef } from 'expo-router'`)
  if (o.reactQuery) L.push(`import { useContext } from 'react'`)
  if (o.realtimeTools?.length)
    L.push('', ...o.realtimeTools.map((t) => `import { ${t.name} } from '${t.from}'`))

  if (o.stores) {
    const stores = o.stores.length ? o.stores : [{ name: 'useAuthStore', from: '../stores/auth' }]
    L.push(
      '',
      '// Zustand stores are left out: they often hold tokens. Add `redact` for those',
      '// paths, then uncomment these and storeTools below. See',
      `// ${DOCS}/adapters.md`,
      `// import { storeTools } from '@avasapp/agent-bridge/zustand'`,
      ...stores.map((s) => `// import { ${s.name} } from '${s.from}'`),
    )
  }
  if (o.mmkv) {
    const mmkv = o.mmkv.length ? o.mmkv : [{ name: 'storage', from: '../storage' }]
    L.push(
      '',
      '// MMKV is left out: it often holds tokens, and mmkv.get returns values as they',
      '// are. Wire only instances without secrets: uncomment these and mmkvTools below.',
      `// See ${DOCS}/adapters.md`,
      `// import { mmkvTools } from '@avasapp/agent-bridge/react-native-mmkv'`,
      ...mmkv.map((m) => `// import { ${m.name} } from '${m.from}'`),
    )
  }
  for (const todo of o.realtime) {
    const r = REALTIME[todo.kind]
    L.push(
      '',
      `// TODO ${todo.kind}: the adapter must wrap the client where it is created,`,
      `// before the app subscribes (${DOCS}/realtime.md).`,
      todo.file
        ? `// In ${todo.file}, right after \`${todo.name}\` is created, add:`
        : `// Where your ${todo.kind} client is created, add:`,
      `//   import { ${r.fn} } from '${r.from}'`,
      `//   ${realtimeLine(todo)}`,
      `// then import realtimeDevTools here and uncomment it in tools.`,
    )
  }

  L.push('')
  if (o.ts) L.push('const scenarios: Scenarios = {')
  else L.push(`/** @type {import('@avasapp/agent-bridge').Scenarios} */`, 'const scenarios = {')
  if (o.network) {
    L.push(
      '  offline: {',
      `    description: 'Every request fails like a network failure; Metro still gets through.',`,
      '    apply: ({ onUndo }) => {',
      '      onUndo(strictNetwork({ offline: true }))',
      '    },',
      '  },',
    )
  }
  L.push(
    '  // A user signed in locally with every request mocked: the state most flows',
    `  // start from. See ${DOCS}/scenarios.md`,
    '  // signedIn: {',
    `  //   description: 'Signed in locally; no request reaches a server.',`,
    '  //   apply: async ({ call, onUndo }) => {',
    `  //     onUndo(strictNetwork())  // and mockApi, both from '@avasapp/agent-bridge/network'`,
    `  //     onUndo(mockApi(API_URL, { 'GET /me': { json: user } }))`,
    `  //     await call('store.set', 'auth', { token: 'local', user })`,
    '  //     return { user }',
    '  //   },',
    '  // },',
    '}',
    '',
    'export function AgentBridge() {',
  )
  if (o.reactQuery)
    L.push(
      '  // Undefined outside a QueryClientProvider: mount this inside one for query.* tools.',
      '  const queryClient = useContext(QueryClientContext)',
    )
  L.push(
    '  useAgentBridge({',
    `    name: '${o.appName.replace(/[\\']/g, '\\$&')}',`,
    `    transports: [${o.expo ? 'expoTransport(), ' : ''}cdpTransport()],`,
    '    tools: {',
  )
  if (o.reactQuery) L.push('      ...(queryClient ? queryTools(queryClient) : {}),')
  if (o.expoRouter)
    L.push('      ...routerTools(router, { navigation: useNavigationContainerRef() }),')
  if (o.webview)
    L.push(
      `      // Each WebView also needs useWebViewTools (${DOCS}/webviews.md).`,
      '      ...webviewTools(),',
    )
  if (o.network) L.push('      ...networkTools(),')
  for (const t of o.realtimeTools ?? []) L.push(`      ...${t.name},`)
  if (o.stores) {
    const stores = o.stores.length ? o.stores : [{ name: 'useAuthStore', from: '' }]
    const map = stores.map((s) => `${storeKey(s.name)}: ${s.name}`).join(', ')
    const first = storeKey(stores[0]!.name)
    L.push(`      // ...storeTools({ ${map} }, { redact: { ${first}: ['token'] } }),`)
  }
  if (o.mmkv) {
    const mmkv = o.mmkv.length ? o.mmkv : [{ name: 'storage', from: '' }]
    L.push(`      // ...mmkvTools({ ${mmkv.map((m) => m.name).join(', ')} }),`)
  }
  if (o.realtime.length) L.push('      // ...realtimeDevTools,')
  if (o.reactNavigation) {
    const params = o.ts ? 'name: string, params?: object' : 'name, params'
    L.push(
      '      // React Navigation has no adapter. With your container ref',
      '      // (createNavigationContainerRef from @react-navigation/native), tools like these work:',
      `      // 'nav.navigate': (${params}) => navigationRef.navigate(name, params),`,
      `      // 'nav.current': () => navigationRef.getCurrentRoute(),`,
    )
  }
  L.push(
    `      // Your own tools: any function, JSON in and out, e.g. 'cart.clear': () => clearCart(),`,
    '    },',
    '    scenarios,',
    '  })',
    '  return null',
    '}',
    '',
  )
  return L.join('\n')
}

/** The two lines to paste into the root component. */
export function renderMountSnippet(importPath: string): string {
  return `import { AgentBridge } from '${importPath}'\n{__DEV__ ? <AgentBridge /> : null}`
}

export type SmokeFlowInput = { version: string; expoRouter: boolean; bin: string }

export function renderSmokeFlow(o: SmokeFlowInput): string {
  return [
    `// Generated by agent-bridge init ${o.version}. Run it with:`,
    `//   ${o.bin} run flows/smoke.flow.mjs`,
    `/** @type {import('@avasapp/agent-bridge/client').FlowModule['default']} */`,
    'const smoke = async ({ step }) => {',
    `  await step('snapshot', 'screen.snapshot')`,
    ...(o.expoRouter ? [`  await step('open home', 'router.navigate', '/')`] : []),
    '  // TODO: wait for text your first screen always shows, for example:',
    `  // await step('home shown', 'screen.waitFor', 'Welcome')`,
    `  await step('undo', 'bridge.restore')`,
    '}',
    '',
    'export default smoke',
    '',
  ].join('\n')
}

export function renderFlowsReadme(bin: string): string {
  return `Flows for \`${bin} run flows/<name>.flow.mjs\`: plain .mjs files named \`*.flow.mjs\`, kept out of \`app/\` and test globs. See ${DOCS}/cli.md#flows-where-they-go.\n`
}

export function agentsLine(flowsDir: string, bin: string): string {
  return `- Flows for agent-bridge live in \`${flowsDir}/<name>.flow.mjs\` (never under \`app/\`, never \`*.test.*\`); run one with \`${bin} run ${flowsDir}/smoke.flow.mjs\`.`
}

export type Patch = { text: string } | { unchanged: true } | { manual: string }

const indentOf = (text: string) => text.match(/^([ \t]+)"/m)?.[1] ?? '  '

function patchJson(
  text: string,
  // oxlint-disable-next-line no-explicit-any -- arbitrary JSON config
  edit: (json: any) => boolean,
  manual: string,
): Patch {
  let json: unknown
  try {
    json = JSON.parse(text)
  } catch {
    return { manual }
  }
  if (!json || typeof json !== 'object' || Array.isArray(json)) return { manual }
  if (!edit(json)) return { unchanged: true }
  return {
    text: JSON.stringify(json, null, indentOf(text)) + (text.endsWith('\n') ? '\n' : ''),
  }
}

/** Adds `"flow": "agent-bridge run"` unless a flow script exists. */
export function patchPackageScripts(text: string): Patch {
  return patchJson(
    text,
    (pkg) => {
      if (pkg.scripts?.flow !== undefined) return false
      pkg.scripts = { ...pkg.scripts, flow: 'agent-bridge run' }
      return true
    },
    `Add to package.json scripts: "flow": "agent-bridge run"`,
  )
}

/** Adds the flow glob to tsconfig `exclude`, keeping node_modules (an explicit list replaces the default). */
export function patchTsconfig(text: string): Patch {
  return patchJson(
    text,
    (tsconfig) => {
      const exclude: unknown[] = Array.isArray(tsconfig.exclude) ? tsconfig.exclude : ['node_modules']
      if (exclude.includes(FLOW_GLOB)) return false
      if (!exclude.includes('node_modules')) exclude.unshift('node_modules')
      tsconfig.exclude = [...exclude, FLOW_GLOB]
      return true
    },
    `Add to tsconfig.json: "exclude": ["node_modules", "${FLOW_GLOB}"]`,
  )
}

export function patchOxlint(text: string): Patch {
  return patchJson(
    text,
    (config) => {
      const ignore: unknown[] = Array.isArray(config.ignorePatterns) ? config.ignorePatterns : []
      if (ignore.includes(FLOW_GLOB)) return false
      config.ignorePatterns = [...ignore, FLOW_GLOB]
      return true
    },
    `Add to .oxlintrc.json: "ignorePatterns": ["${FLOW_GLOB}"]`,
  )
}

export const ESLINT_SNIPPET = `{ ignores: ['${FLOW_GLOB}'] },`

/**
 * Prepends the ignore entry to a flat config exported as a plain array or a
 * `defineConfig([...])` literal; anything else gets the snippet to paste.
 */
export function patchEslint(text: string): Patch {
  if (text.includes(FLOW_GLOB)) return { unchanged: true }
  const manual = `Add to the start of your ESLint flat config array: ${ESLINT_SNIPPET}`
  const re = /^((?:module\.exports\s*=|export\s+default)\s*(?:defineConfig\(\s*)?\[)/gm
  const matches = [...text.matchAll(re)]
  if (matches.length !== 1) return { manual }
  const at = matches[0]!.index! + matches[0]![1]!.length
  return { text: `${text.slice(0, at)}\n  ${ESLINT_SNIPPET}${text.slice(at)}` }
}
